themes.css:
:root {
  --bg: #F7F2E9;      --surface: #FFFDF8;
  --tint: #EFE6D6;          --well: #EBE1CF;
  --outline: #2A2420;    --accent: #D9B872;
  --on-accent: #2A2118; --text: #241F19;
  --muted: #6E6355;
  --control: #F4EEE1;   --raised: #FFFDF8;
  --accent-ink: #635538;
  --separator: color-mix(in srgb, var(--outline) 13%, transparent);
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1A1714;      --surface: #241F1A;
    --tint: #201B16;          --well: #2C251E;
    --outline: #CDBFA6;    --accent: #C9A45E;
    --on-accent: #1A1410; --text: #F0E7D8;
    --muted: #A69884;
    --control: #2C251E;   --raised: #453E36;
    --accent-ink: #C9A45E;
    --separator: color-mix(in srgb, var(--outline) 13%, transparent);
  }
}

